var numberOfScreenshots,
  screenshots = [],
  numberOfChars = 0,
  chap_id = "",
  book_id = "";
function syncTextByLang() {
  "vi" === document.querySelector(".lang-select").value
    ? ((document.querySelector(".lang").textContent = "Language:"),
      (document.querySelector(".recommend").textContent =
        "Cài đặt truyện khuyên dùng: font-size > 20"),
      (document.querySelector(".char-per-page").textContent =
        "Kí tự trên mỗi trang:"),
      (document.querySelector(".char-per-page-memo").textContent =
        "Giảm số kí tự trên mỗi trang nếu gặp lỗi không thể lấy được text do có một số truyện tác viết nhiều chữ làm vượt quá giới hạn của AI"),
      (document.querySelector(".point").textContent =
        "(Sẵn sàng chụp ảnh)"),
      (document.querySelector(".changelogs").textContent =
        'Cập nhật:\n            - 2.2: Cho phép giảm số chữ trên mỗi trang để khắc phục vấn đề một số chương quá nhiều chữ liền nhau gây lỗi không lấy text được\n            - 2.1: Cập nhật màu nên và màu chữ để khắc phục việc chia trang bị lỗi trên server, tránh lỗi text\n            - 2.0: Xoá "rác" theo cách mới, không cần đổi màu nền nữa\n            - 1.5.3: Cập nhật UI và ngôn ngữ\n        '))
    : ((document.querySelector(".lang").textContent = "Ngôn ngữ:"),
      (document.querySelector(".recommend").textContent =
        "Recommend for book setting: font size > 20"),
      (document.querySelector(".char-per-page").textContent =
        "Characters per page:"),
      (document.querySelector(".char-per-page-memo").textContent =
        "Decrease the number of characters per page if you encounter an error that cannot get text because some authors write too many characters that exceed the AI limit"),
      (document.querySelector(".point").textContent =
        "(Ready to capture screenshots)"),
      (document.querySelector(".changelogs").textContent =
        'Changelogs:\n            - 2.2: Allow to decrease number of characters per page to fix issue some chapter has too many characters in a row causing text error\n            - 2.1: Update background color and text color to fix page division error on server, avoid text error\n            - 2.0: Clean "trash" in a new way, no need to change background color\n            - 1.5.3: Update UI and language\n        '));
}
function clean() {
  return (
    document.querySelector(".loading").classList.add("show"),
    new Promise((e) => {
      chrome.tabs.query({ active: !0, currentWindow: !0 }, async function (t) {
        await chrome.scripting.executeScript(
          {
            target: { tabId: t[0].id },
            function: () => {
              Element.prototype.getBoundingClientRect = function () {
                return {
                  top: 1,
                  left: 1,
                  bottom: window.innerHeight,
                  right: window.innerWidth,
                  width: window.innerWidth,
                  height: window.innerHeight,
                };
              };
            },
            world: "MAIN",
          },
          async () => {
            await chrome.scripting.executeScript(
              {
                target: { tabId: t[0].id },
                function: () => {
                  var e = document.createElement("style");
                  ((e.innerHTML =
                    '\n                        #left-container,\n                        #right-container,\n                        #r-breadcrumbs,\n                        #navbar,\n                        #r-authorSay,\n                        .review,\n                        .chapter-end-qrcode,\n                        button,\n                        .nav-btn-group,\n                        .side-button,\n                        div.text-s-gray-500.mt-4px.text-bo4.flex.items-center.flex-wrap,\n                        .chapter-wrapper > .relative > [class*="moreComment"],\n                        img {\n                        display: none !important;\n                        }\n\n                        #reader {\n                        background: black !important;\n                        }\n                        main, #reader-content {\n                        background: black !important;\n                        --width: 95vw;\n                        --surface-gray-900: white;\n                        }\n\n                        body::-webkit-scrollbar {\n                        width: 0;\n                        }\n\n                        body::-webkit-scrollbar-track {\n                        background-color: transparent;\n                        }\n\n                        body::-webkit-scrollbar-thumb {\n                        background-color: transparent;\n                        }\n                        '),
                    document.body.appendChild(e),
                    document.querySelector("main style").remove());
                },
              },
              async () => {
                await chrome.scripting.executeScript(
                  {
                    target: { tabId: t[0].id },
                    function: async () => {
                      window.scrollTo(0, 0);
                      await new Promise((e) => requestAnimationFrame(e));
                      await new Promise((e) => requestAnimationFrame(e));
                      await new Promise((e) => setTimeout(e, 120));
                      var e = document.documentElement.scrollHeight,
                        t = window.innerHeight,
                        n = Math.max(0, e - t);
                      return Math.ceil((n + t) / t) * t;
                    },
                  },
                  async (n) => {
                    ((totalHeight = n[0].result),
                      console.log("Total height:", totalHeight),
                      await chrome.scripting.insertCSS({
                        target: { tabId: t[0].id },
                        css: `\n                                #reader-content {\n                                    height: ${totalHeight}px !important;\n                                }\n                            `,
                      }),
                      document
                        .querySelector(".loading")
                        .classList.remove("show"),
                      e());
                  },
                );
              },
            );
          },
        );
      });
    })
  );
}
function getImages() {
  return new Promise((e, t) => {
    chrome.tabs.query({ active: !0, currentWindow: !0 }, async function (r) {
      const o = r[0].id,
        n = (e) =>
          new Promise((n, r) => {
            chrome.scripting.executeScript(
              {
                target: { tabId: o },
                function: async (e) => {
                  window.scrollTo(0, e);
                  await new Promise((e) => requestAnimationFrame(e));
                  await new Promise((e) => requestAnimationFrame(e));
                  await new Promise((e) => setTimeout(e, 150));
                  return { scrollY: window.scrollY };
                },
                args: [e],
              },
              (e) => {
                if (chrome.runtime.lastError) return r(chrome.runtime.lastError);
                n(e && e[0] ? e[0].result : { scrollY: -1 });
              },
            );
          }),
        i = () =>
          new Promise((e, t) => {
            chrome.tabs.captureVisibleTab().then(e).catch(t);
          }),
        s = () =>
          new Promise((resolve, reject) => {
            chrome.scripting.executeScript(
              {
                target: { tabId: o },
                function: () => {
                  var e = document.documentElement.scrollHeight,
                    t = window.innerHeight,
                    n = Math.max(0, e - t),
                    r = [];
                  for (let o = 0; o <= n; o += t) r.push(o);
                  return (
                    0 !== r[0] && r.unshift(0),
                    r.length && r[r.length - 1] !== n && r.push(n),
                    { positions: [...new Set(r)], totalShot: r.length }
                  );
                },
              },
              (result) => {
                if (chrome.runtime.lastError)
                  return reject(chrome.runtime.lastError);
                const data =
                  result && result[0] && result[0].result
                    ? result[0].result
                    : null;
                if (!data)
                  return reject(new Error("Cannot compute capture positions"));
                resolve(data);
              },
            );
          });
      try {
        document.querySelector(".loading").classList.add("show");
        const r = await s(),
          c = [];
        numberOfScreenshots = r.totalShot;
        console.log("Total shots:", numberOfScreenshots, "Chap id:", chap_id);
        let a = await n(0);
        0 !== Math.round(a.scrollY) && (a = await n(0));
        for (let e = 0; e < r.positions.length; e++) {
          await n(r.positions[e]);
          try {
            c.push(await i());
          } catch (t) {
            if (0 !== e) throw t;
            c.push(await i());
          }
        }
        (screenshots = c), e();
      } catch (e) {
        t(e);
      } finally {
        document.querySelector(".loading").classList.remove("show");
      }
    });
  });
}
function saveScreenshots() {
  screenshots.forEach((e, t) => {
    const n = document.createElement("a");
    ((n.href = e),
      (n.download = `${chap_id || "qidian"}_${String(t + 1).padStart(3, "0")}.png`),
      n.click());
  });
}
(chrome.tabs.query({ active: !0, currentWindow: !0 }, function (e) {
  e[0].url.includes("qidian.com")
    ? (document.querySelector(".warning").style.display = "none")
    : ((document.querySelector(".content").style.display = "none"),
      (document.querySelector(".warning").style.display = "block"));
  chrome.scripting.executeScript(
    {
      target: { tabId: e[0].id },
      function: () => {
        var e = document
            .querySelector("span.group.inline-flex.items-center.mr-16px")
            .textContent.split(" ")
            .pop(),
          t = e.match(/万/);
        return {
          totalChar: parseFloat(e.replace(/[^0-9.]/g, "")) * (t ? 1e4 : 1),
          chap_id: window.location.pathname
            .match(/chapter\/(.+)/)[1]
            .replace(/\//g, "__"),
        };
      },
    },
    (e) => {
      ((numberOfChars = e[0].result.totalChar),
        (chap_id = e[0].result.chap_id),
        (book_id = chap_id.split("__")[0]),
        console.log(
          "Total chars:",
          numberOfChars,
          "Chap id:",
          chap_id,
          "Book id:",
          book_id,
        ));
    },
  );
}),
  document.querySelector(".lang-select").addEventListener("change", (e) => {
    (chrome.storage.sync.set({ lang: e.target.value }), syncTextByLang());
  }),
  document
    .querySelector('input[name="token"]')
    .addEventListener("input", (e) => {
      (chrome.storage.sync.set({ token: e.target.value }),
        e.target.value
          ? document.querySelectorAll(".need-token").forEach((e) => {
              e.classList.remove("disable");
            })
          : document.querySelectorAll(".need-token").forEach((e) => {
              e.classList.add("disable");
            }));
    }),
  document.addEventListener("DOMContentLoaded", () => {
    (chrome.storage.sync.get("token", (e) => {
      ((document.querySelector('input[name="token"]').value = e.token || ""),
        e.token &&
          document.querySelectorAll(".need-token").forEach((e) => {
            e.classList.remove("disable");
          }));
    }),
      chrome.storage.sync.get("lang", (e) => {
        (e.lang && (document.querySelector(".lang-select").value = e.lang),
          syncTextByLang());
      }));
  }));
var cleanButton = document.getElementById("clean");
cleanButton.addEventListener("click", clean);
var getNewTextButton = document.getElementById("getNewText");
getNewTextButton.addEventListener("click", async function () {
  try {
    (screenshots.length = 0), await clean(), await getImages(), saveScreenshots();
  } catch (e) {
    (console.error("Capture failed:", e),
      alert("Capture failed. Please try again."));
  } finally {
    document.querySelector(".loading").classList.remove("show");
  }
});
